render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, y = cfg$y), c("x", "y")); radii <- sqrt(data[[cfg$y]] / pi); ang <- seq(0, 2 * pi, length.out = nrow(data) + 1)[-(nrow(data) + 1)]; rr <- max(radii) * 2.2; cx <- rr * cos(ang); cy <- rr * sin(ang); chart_open_device(cfg$outputPath, cfg$format); plot(NA, xlim = c(-rr * 1.6, rr * 1.6), ylim = c(-rr * 1.6, rr * 1.6), asp = 1, axes = FALSE, xlab = "", ylab = "", main = cfg$title %||% "圆形打包图"); for (i in seq_along(radii)) { symbols(cx[i], cy[i], circles = radii[i], inches = FALSE, add = TRUE, bg = grDevices::adjustcolor(cfg$color %||% "#0A84FF", alpha.f = 0.55), fg = "white"); text(cx[i], cy[i], labels = as.character(data[[cfg$x]][i]), cex = 0.9); }; box(); grDevices::dev.off(); cfg$outputPath }
